RequireJS.define('text!teams/templates/team-membership-details.underscore',[],function () { return '<span class="member-count"><%- membership_message %></span>\n<ul class="list-member-thumbs">\n    <% _.each(memberships, function (membership) { %>\n        <li class="item-member-thumb"><img alt="<%- membership.user.username %>" src="<%- membership.user.profile_image.image_url_small %>"></img></li>\n    <% }) %>\n    <% if (has_additional_memberships) { %>\n        <li class="item-member-thumb"><span class="sr"><%- sr_message %></span>&hellip;</li>\n    <% } %>\n</ul>\n';});


RequireJS.define('text!teams/templates/team-country-language.underscore',[],function () { return '<% if (country) { print(\'<p class="meta-detail team-location"><span class="icon fa-globe"></span>\' + country + \'</p>\'); } %>\n<% if (language) { print(\'<p class="meta-detail team-language"><span class="icon fa-comment"></span>\' + language + \'</p>\'); } %>\n';});


